* { box-sizing: border-box; }
.page { width: 600px; gap: 8px; }
.header { background: #0b6fd6; color: white; padding: 12px; }
.sidebar { background: #0aa5b8; color: white; padding: 12px; }
.main { background: #dcebfb; padding: 12px; min-height: 80px; }
.footer { background: #12304f; color: white; padding: 12px; }
.page {
  display: grid;
  grid-template-columns: 160px 1fr;
  grid-template-areas:
    "header  header"
    "sidebar main"
    "footer  footer";
}
.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.footer  { grid-area: footer; }

